import networkx as nx
import itertools
import random

def is_valid(G):
    if G.number_of_nodes() != 13:
        return False
    if min(dict(G.degree()).values()) < 4:
        return False
    # Correct way to get clique number
    if nx.algorithms.clique.graph_clique_number(G) > 5:
        return False
    # Correct way to get chromatic number
    if nx.algorithms.coloring.greedy_color(G, strategy='largest_first') is not None:
        # greedy_color returns a dict, the number of colors is max(dict.values()) + 1
        coloring = nx.algorithms.coloring.greedy_color(G, strategy='largest_first')
        if max(coloring.values()) + 1 > 5:
            return False
    return True

fixed_edges = [(1,3), (2,7), (3,11), (3,10), (0,12), (2,10), (2,4), (1,11)]

def solve():
    for _ in range(50000):
        G = nx.Graph()
        G.add_nodes_from(range(13))
        G.add_edges_from(fixed_edges)

        # Add edges until all degrees are at least 4
        # To keep it simple, let's just add random edges
        possible_edges = list(itertools.combinations(range(13), 2))
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            if not G.has_edge(u, v):
                G.add_edge(u, v)
                if min(dict(G.degree()).values()) >= 4:
                    break

        if is_valid(G):
            return list(G.edges())
    return None

result = solve()
print(result)
